/**
 * @name HTTP Header Injection
 * @description User input flowing into HTTP headers without validation can lead to CRLF injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/header-injection
 * @tags security
 *       external/cwe/cwe-113
 */
import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module HeaderInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for h11 Request headers
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("h11").getMember("Request").getACall() and
      (
        sink = call.getArgByName("headers") or
        sink = call.getArg(1)
      )
    )
    or
    // Look for h2 send_headers
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("h2").getMember("connection").getMember("H2Connection").getReturn().getMember("send_headers").getACall() and
      (
        sink = call.getArgByName("headers") or
        sink = call.getArg(1)
      )
    )
  }
}

module HeaderInjectionFlow = TaintTracking::Global<HeaderInjectionConfig>;
import HeaderInjectionFlow::PathGraph

from HeaderInjectionFlow::PathNode source, HeaderInjectionFlow::PathNode sink
where HeaderInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential HTTP Header Injection from $@", source.getNode(), "parameter"
